"""Turns an EvidenceSubgraph into a human-readable reason string.

**Rule-based templates, never an LLM.** If explanations were generated by an LLM, the
explanation itself would become a second black box on top of the first -- an analyst or
regulator couldn't audit *why* the explanation says what it says, which defeats the entire
point of this workstream (see docs/team/PROMPT_C_explain_api_ui.md: "under GDPR-style right to
explanation ... a bank must justify why an account was frozen"). Every string this module can
produce is enumerable ahead of time from the template set below, and the same evidence subgraph
always produces the same reason -- that determinism is the auditability guarantee.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Dict, List, Optional

from src.explain.evidence import EvidenceSubgraph
from src.utils.config import get_logger, load_config

logger = get_logger(__name__)

FEATURE_NAMES_UNKNOWN_MSG = (
    "these {n} edges mattered most" \
    " (feature names are anonymised in this dataset, so only graph structure is reportable)"
)


@dataclass
class ReasonContext:
    """Everything the templates need, gathered by the API layer before calling `generate_reason`.

    Kept separate from EvidenceSubgraph because this data (entity labels, inflow stats) comes
    from A's node metadata (`bundle.nodes[...]['node_id']`) and B's ring extraction, not from
    the explainer itself.
    """

    node_id_map: Dict[int, str] = field(default_factory=dict)      # idx -> human node_id string
    node_type_map: Dict[int, str] = field(default_factory=dict)    # idx -> 'card' | 'device' | ...
    feature_names: Optional[List[str]] = None                       # None => anonymised dataset
    shared_entity_idx: Optional[int] = None                         # e.g. the hub device node
    shared_entity_count: Optional[int] = None                       # how many accounts share it
    inflow_pct: Optional[float] = None                               # 0-100
    inflow_window_hours: Optional[int] = None


def generate_reason(evidence: EvidenceSubgraph, ctx: ReasonContext) -> str:
    """Deterministically render one of the fixed templates below from `evidence` + `ctx`.

    Priority order (first that has enough data wins):
      1. Shared-entity + inflow-concentration sentence -- the richest, most actionable template,
         used when the data is IEEE-CIS-style (human-meaningful entity nodes) and we have both
         a shared entity and an inflow stat.
      2. Shared-entity only -- same dataset, but no inflow stat available for this target.
      3. Structural-only fallback -- used for anonymised datasets (Elliptic-style) where feature
         names carry no meaning, so we can only say which edges/features mattered, not why.
    """
    if ctx.shared_entity_idx is not None and ctx.shared_entity_count is not None:
        entity_label = ctx.node_id_map.get(ctx.shared_entity_idx, f"entity #{ctx.shared_entity_idx}")
        if ctx.inflow_pct is not None and ctx.inflow_window_hours is not None:
            return (
                f"Flagged because {ctx.shared_entity_count} accounts share {entity_label}, "
                f"and {ctx.inflow_pct:.0f}% of inflow in {ctx.inflow_window_hours}h "
                f"came from that cluster."
            )
        return (
            f"Flagged because {ctx.shared_entity_count} accounts share {entity_label}, "
            f"linked through {len(evidence.edges)} of the account's strongest connections."
        )

    return _structural_reason(evidence, ctx)


def _structural_reason(evidence: EvidenceSubgraph, ctx: ReasonContext) -> str:
    n = len(evidence.edges)
    if n == 0:
        return "Flagged, but no supporting edges reached the evidence threshold -- review manually."

    if ctx.feature_names:
        top = [
            f"{ctx.feature_names[i]} ({imp:.2f})"
            for i, imp in evidence.top_features
            if i < len(ctx.feature_names)
        ]
        feat_clause = f" Top contributing features: {', '.join(top)}." if top else ""
    else:
        feat_clause = ""

    return (
        f"Flagged based on graph structure: {n} strongest connecting edge"
        f"{'s' if n != 1 else ''} to this account drove the prediction "
        f"(feature names are anonymised in this dataset, so only structure is reportable)."
        f"{feat_clause}"
    )
